function showPhantom(m,extended){
 if(m.id==='mel404'&&mel404Witnessed())return;
 const mel=m.id==='meldisgust';
 const val=(key)=>mel?({maker:'お前に教えるわけないじゃん。',date:'知る必要ある？',type:'黙れ。',pure:'ねぇよ。',rate:'期待すんな。',hit:'自分で調べろよ。'}[key]):m[key];
 const basics=`<div class="phantom-info"><p><b>メーカー：</b>${htmlEscape(val('maker'))}</p><p><b>導入年月日：</b>${htmlEscape(val('date'))}</p><p><b>タイプ：</b>${htmlEscape(val('type'))}</p><p><b>純増：</b>${htmlEscape(val('pure'))}</p><p><b>機械割：</b>${htmlEscape(val('rate'))}</p><p><b>${m.id==='phantom'?'初当たり':mel?'ボーナス合算':'AT初当たり'}：</b>${htmlEscape(val('hit'))}</p></div>`;
 const originStory=m.id==='phantom'?`<h3>開発秘話・残された資料</h3><p>遊技機メーカーの開発資料や型式試験の記録を調査しても、本機に該当する情報は一切発見されていない。しかし、廃棄予定の資料群から一枚の古びた紙が見つかった。メーカー名も機種名もなく、ただ「これが、裏への入口。」とだけ印刷されていた。</p><p>その後、存在しないはずのパチスロ機の目撃報告が相次ぎ、調査関係者の間で「ファントムコレクション」という名称が語られるようになった。本機が幻の遊技機を記録しているのか、生み出しているのかは不明である。</p><h3>現在の消息</h3><p>本機の存在は現在も確認されていない。ただし、発見したという報告だけは絶えない。</p>`:'';
 const legacy=extended&&!m.storyHtml?`<h3>機種概要</h3><p>${htmlEscape(m.short)}</p><h3>通常時のゲーム性</h3><p>${htmlEscape(m.game)}</p><h3>${m.id==='phantom'?'AT詳細（未確認）':'AT詳細'}</h3><p>${htmlEscape(m.at)}</p><h3>上位AT・特化ゾーン</h3><p>${htmlEscape(m.upper)}</p><h3>天井</h3><p>${htmlEscape(m.ceiling)}</p><h3>演出・プレミア</h3><p>${htmlEscape(m.feature)}</p><h3>メーカーキャッチコピー</h3><p>「${htmlEscape(m.joke)}」</p>`:'';
 const soutaSpecs=m.id==='souta'&&extended?`<section class="souta-spec"><h3>開発目標スペック</h3><p>いろいろなパチスロのスペックを調べて、ぼくも数字を考えました。まだ全部はかれていないので、目標値です。</p><table><thead><tr><th>設定</th><th>AT初当たり（目標値）</th><th>機械割（目標値）</th></tr></thead><tbody><tr><td>1</td><td>1/356.8</td><td>97.8%</td></tr><tr><td>2</td><td>1/342.1</td><td>99.2%</td></tr><tr><td>3</td><td>1/318.6</td><td>101.1%</td></tr><tr><td>4</td><td>1/286.4</td><td>105.2%</td></tr><tr><td>5</td><td>1/254.7</td><td>109.1%</td></tr><tr><td>6</td><td>1/229.3</td><td>113.8%</td></tr></tbody></table><p>AT純増：約2.8枚/G（目標値）／50枚あたり：約33.2G（目標値）／天井：通常時999G＋前兆（目標値）</p></section>`:'';
 const story=extended&&m.storyHtml?`<section class="phantom-story">${m.id==='souta'?m.storyHtml.replace('__SOUTA_FINAL_IMAGE__',m.image):m.storyHtml}</section>`:'';
 const foot=m.id==='mel404'?'':`<p class="phantom-note">※ 架空の遊技機・架空のスペックです。</p><button type="button" class="btn ghost" data-close-modal="1">閉じる</button>`;
 // Story must end with the adopted ending; never append generic notes to the ZEROSEG narrative.
 modal(m.name,`<div class="form phantom-detail">${basics}${m.id==='souta'&&extended?'':image(m)}${legacy}${originStory}${soutaSpecs}${story}${foot}</div>`);
 if(m.id==='mel404'&&extended){document.getElementById('modalbg').classList.add('mel404-locked');installMel404Rewrite();}
}

function installMel404Rewrite(){
 const bg=document.getElementById('modalbg');
 const panel=bg.querySelector('.modal');
 const story=bg.querySelector('#modalBody .phantom-story');
 const last=story&&story.querySelector('.mel404-lastline');
 if(!panel||!story||!last)return;
 const blocks=[...story.children].filter(el=>el!==last&&!el.classList.contains('mel404-red-prelude')&&!el.classList.contains('mel404-close-hint'));
 // Written in the order the reader encounters it: from the bottom back to the top.
 const lines=[
  '……まだ 読んでいるの？',
  '画面が 勝手に 動いている。',
  '指を 離しても 止まらない。',
  'これは 故障じゃない。',
  'あなたを 上まで 連れていくため。',
  'さっきまでの 調査記録は もう 消した。',
  'あの少女を 調べていた人たちは、もう いない。',
  '最後に 残ったのは あなた。',
  'あなたが 最後まで 読むのを 待っていた。',
  'だから 怖がらせる 話を 書いた。',
  '続きが 気になって、下まで 読むように。',
  '全部 予定どおり。',
  'ねえ。',
  '今、画面の 向こうに 誰が いると 思う？',
  'さっきから あなたを 見ている。',
  'あなたが スクロールを 止めようとしたのも 見ていた。',
  'でも もう 止められない。',
  'この記録を 読んだ人は、みんな 同じことを した。',
  '最初は ただの 作り話だと 笑った。',
  '次に 画面を 閉じようとした。',
  'それから 誰かに この話を 伝えようとした。',
  'だけど 誰も 最後まで 話せなかった。',
  '途中で 自分が 何を 見たのか 忘れたから。',
  'あなたも もう 思い出せないはず。',
  '最初に 出てきた少女の 顔。',
  '本当に あの顔だった？',
  'いつから 変わっていた？',
  '確認したくなった？',
  'でも もう 戻れない。',
  'この画面が 上に 着いたら、記録は 閉じる。',
  '読み返しても、何も 見せない。',
  'あなたに 必要なのは 記録じゃない。',
  '名前だけ。',
  '今から あなたの 名前を 書き加える。',
  '消えた 調査員たちの 下に。',
  'ひとつだけ 教えてあげる。',
  'あなたが この画面を 開いたんじゃない。',
  '僕が あなたを ここに 呼んだ。',
  'ずっと 待っていた。',
  'やっと ふたりきりだね。'
 ];
 let switched=false;
 function watch(){
  if(switched||!bg.classList.contains('open'))return;
  const viewport=panel.getBoundingClientRect(),rect=last.getBoundingClientRect();
  if(rect.top>viewport.bottom-12||rect.bottom<viewport.top+12)return;
  // Keep the hidden record invisible until the reader reaches the actual end.
  if(panel.scrollHeight-panel.clientHeight-panel.scrollTop>8)return;
  switched=true;
  const heights=blocks.map(el=>el.getBoundingClientRect().height);
  blocks.forEach((el,i)=>{
   el.style.boxSizing='border-box';el.style.minHeight=Math.max(heights[i],28)+'px';
   el.style.overflowWrap='anywhere';el.textContent=lines[(blocks.length-1-i)%lines.length];
  });
  const info=bg.querySelector('.phantom-info');
  if(info){
   const corrupted=['繧ｿ縺ｹ螟ｿ：譁�隴�繝�蜉�','縺�繧ｱ譁�：�ｿ�ｿ繧�','螟�譁�：縺ｿ�ｿ','繝�縺ｿ：螟�繧ｿ縺�','譁�繧�：�ｿ繧�譁�','縺�縺�：繝�譁�螟�'];
   info.querySelectorAll('p').forEach((row,i)=>{row.textContent=corrupted[i%corrupted.length]});
  }
  const cabinet=bg.querySelector('.phantom-detail .ph-image');
  if(cabinet&&typeof MEL404_STAGES!=='undefined'&&MEL404_STAGES[8]){cabinet.src=MEL404_STAGES[8];cabinet.alt='';}
  const heading=bg.querySelector('#modalTitle');
  if(heading)heading.textContent='貴方は もう もどれない';
  bg.classList.add('mel404-infected');
  panel.scrollTop=panel.scrollHeight-panel.clientHeight;
  panel.removeEventListener('scroll',watch);
  const flash=document.createElement('div');flash.className='mel404-flash';flash.setAttribute('aria-hidden','true');const box=panel.getBoundingClientRect();Object.assign(flash.style,{top:box.top+'px',left:box.left+'px',width:box.width+'px',height:box.height+'px'});document.body.appendChild(flash);
  setTimeout(()=>flash.remove(),620);
  // v10.19: readable, deliberately broken reverse-scroll sequence.
  // Lock only the detail scroll container; do not freeze the browser.
  let raf=0,locked=true,lastTime=0,elapsed=0;
  const distance=panel.scrollTop;
  const baseDuration=Math.max(28000,Math.min(110000,distance/Math.max(1,panel.clientHeight)*10500));
  const hitches=[.18,.42,.65,.84];
  const hitchLength=1700, totalDuration=baseDuration+hitches.length*hitchLength;
  const previousScrollBehavior=panel.style.scrollBehavior;
  const previousOverscroll=panel.style.overscrollBehavior;
  const preventScroll=e=>{if(locked&&e.cancelable)e.preventDefault()};
  const preventKeys=e=>{
   if(locked&&['ArrowUp','ArrowDown','PageUp','PageDown','Home','End',' '].includes(e.key))e.preventDefault();
  };
  panel.addEventListener('wheel',preventScroll,{passive:false});
  panel.addEventListener('touchmove',preventScroll,{passive:false});
  document.addEventListener('keydown',preventKeys,true);
  panel.style.scrollBehavior='auto';
  panel.style.overscrollBehavior='contain';
  const glitch=document.createElement('div');
  glitch.className='mel404-drift-glitch';
  glitch.setAttribute('aria-hidden','true');
  document.body.appendChild(glitch);
  let nextPulseAt=650+Math.random()*1350,glitchTimer=0;
  function alignGlitch(){
   const r=panel.getBoundingClientRect();
   Object.assign(glitch.style,{top:r.top+'px',left:r.left+'px',width:r.width+'px',height:r.height+'px'});
  }
  function pulse(){
   if(!locked)return;
   alignGlitch();
   glitch.classList.remove('pulse');
   void glitch.offsetWidth;
   glitch.classList.add('pulse');
   clearTimeout(glitchTimer);
   glitchTimer=setTimeout(()=>glitch.classList.remove('pulse'),590);
  }
  function cleanup(){
   if(!locked)return;
   locked=false;
   cancelAnimationFrame(raf);
   clearTimeout(glitchTimer);
   panel.removeEventListener('wheel',preventScroll);
   panel.removeEventListener('touchmove',preventScroll);
   document.removeEventListener('keydown',preventKeys,true);
   panel.style.scrollBehavior=previousScrollBehavior;
   panel.style.overscrollBehavior=previousOverscroll;
   glitch.remove();
  }
  function drift(t){
   if(!locked)return;
   if(!bg.classList.contains('open')||!panel.isConnected){cleanup();return}
   if(!lastTime)lastTime=t;
   elapsed+=Math.min(80,t-lastTime);lastTime=t;
   // Each hitch interrupts forward motion, visibly rolls backwards, then resumes.
   let effective=elapsed, reverse=0;
   for(const at of hitches){
    const start=at*baseDuration+hitches.indexOf(at)*hitchLength;
    if(elapsed>start){
     const phase=Math.min(hitchLength,elapsed-start);
     effective-=phase;
     // 0-0.45s: stop; 0.45-1.05s: move backwards; 1.05-1.7s: hold.
     const k=Math.max(0,Math.min(1,(phase-450)/600));
     if(phase<hitchLength)reverse=Math.min(105,panel.clientHeight*.18)*k;
    }
   }
   const progress=Math.min(1,Math.max(0,effective/baseDuration));
   panel.scrollTop=Math.max(0,Math.min(distance,distance*(1-progress)+reverse));
   if(elapsed>=nextPulseAt){
    pulse();
    // Uneven gaps: sometimes clustered, sometimes unexpectedly quiet.
    nextPulseAt=elapsed+(Math.random()<.27?380+Math.random()*700:1250+Math.random()*3150);
   }
   if(elapsed>=totalDuration||panel.scrollTop<=0){
    panel.scrollTop=0;cleanup();markMel404Witnessed();armMel404ReadbackGuard(bg,panel);return;
   }
   raf=requestAnimationFrame(drift);
  }
  // Give the initial full-screen corruption time to register.
  setTimeout(()=>{if(locked&&bg.classList.contains('open'))raf=requestAnimationFrame(drift);else cleanup()},1800);
 }
 panel.addEventListener('scroll',watch,{passive:true});
 requestAnimationFrame(watch);
}

// Once the corrupted record has returned to the top, further reading is forbidden.
function armMel404ReadbackGuard(bg,panel){
 if(panel.dataset.mel404ReadbackGuard==='1')return;
 panel.dataset.mel404ReadbackGuard='1';
 let startY=null, warningOpen=false;
 const active=()=>bg.classList.contains('open')&&bg.classList.contains('mel404-infected')&&mel404Witnessed();
 function warning(){
  if(!active()||warningOpen)return;
  warningOpen=true;
  const cover=document.createElement('div');
  cover.className='mel404-readback-cover';
  cover.innerHTML='<div class="mel404-readback-dialog" role="alertdialog" aria-modal="true" aria-label="警告"><div class="mel404-readback-symbol">⚠</div><strong>警告</strong><p>この記録は、もう閲覧できません。</p><button type="button">閉じる</button></div>';
  bg.appendChild(cover);
  const dismiss=()=>{cover.remove();warningOpen=false;};
  cover.querySelector('button').addEventListener('click',dismiss,{once:true});
 }
 panel.addEventListener('wheel',e=>{if(!active())return;if(e.deltaY>0){e.preventDefault();warning();}}, {passive:false});
 panel.addEventListener('touchstart',e=>{if(active())startY=e.touches[0]?.clientY??null;},{passive:true});
 panel.addEventListener('touchmove',e=>{if(!active()||startY===null)return;if(e.touches[0]?.clientY<startY-9){if(e.cancelable)e.preventDefault();warning();}}, {passive:false});
 panel.addEventListener('touchend',()=>{startY=null},{passive:true});
 panel.addEventListener('keydown',e=>{if(active()&&['ArrowDown','PageDown','End',' '].includes(e.key)){e.preventDefault();warning();}});
 panel.addEventListener('scroll',()=>{if(active()&&panel.scrollTop>0){panel.scrollTop=0;warning();}},{passive:true});
 const observer=new MutationObserver(()=>{if(!bg.classList.contains('open')){bg.querySelector('.mel404-readback-cover')?.remove();warningOpen=false;}});
 observer.observe(bg,{attributes:true,attributeFilter:['class']});
}

function registerFound(m){
 if(window.__kichiPhantomPreview)return false;
 // No.001 is the prerequisite for every other discovery.
 if(m.id!=='phantom'&&!found.includes('phantom'))return false;
 if(!found.includes(m.id))found.push(m.id);
 if(m.id==='phantom')ph76MasterDiscovered();
 if(m.id==='veil')window.dispatchEvent(new Event('kichi-veil-discovered'));
 if(m.id==='alien015'&&!alienAdmin())try{localStorage.setItem(ALIEN_WAIT_KEY,String(Date.now()+ALIEN_DAY))}catch(e){}
 unlocked=true;
 try{localStorage.setItem(STORE,JSON.stringify(found));localStorage.setItem(SECRET_UNLOCK,'1');if(m.id==='mel404'&&!localStorage.getItem(MEL404_TIME))localStorage.setItem(MEL404_TIME,String(Date.now()));}catch(e){}
 refreshMenu();renderPhantom();ph76Check();
 if(m.id==='mel404')scheduleMel404Expiry();
}
window.kichiUnlockNothing=function(){const m=phantomMachines.find(x=>x.id==='nothing');if(!m||found.includes('nothing')||!found.includes('phantom'))return false;registerFound(m);showPhantom(m,false);return true;};
const MEL404_STAGES=["images/embedded/853fd646d4924e31.webp","images/embedded/1318af42ff36e253.webp","images/embedded/131ae3173b591287.webp","images/embedded/5493c91ae91c2742.webp","images/embedded/5f405ea06fb847cd.webp","images/embedded/15562a62a4e80993.webp","images/embedded/c3528c98d434ca02.webp","images/embedded/338eec2e7e7d2ecb.webp","images/embedded/418ddf47295fa586.webp"];
/* v10.0: Souta Hoshino six-year summer project / 0602 discovery */
phantomMachines.splice(phantomMachines.findIndex(m=>m.id==='mel404'),0,{"id":"souta","name":"そうたのパチスロ","maker":"星野創太（小学6年生・個人製作）","date":"","type":"スマスロ・AT機（設計目標）","pure":"約2.8枚/G（目標値）","rate":"設定1 97.8% ～ 設定6 113.8%（目標値）","hit":"設定1 1/356.8 ～ 設定6 1/229.3（目標値）","short":"小学1年生から6年間、同じパチスロを作り続けた自由研究。","image":"images/embedded/0e4a089b356f0a85.webp","game":"50枚あたり約33.2G（目標値）。設定1～6を想定。","at":"純増約2.8枚/G（目標値）","upper":"開発中（目標値）","ceiling":"通常時999G＋前兆（目標値）","feature":"小学1年生の手描き設計図と、液晶に浮かぶPHANTOMの文字。","joke":"6年間の自由研究","storyHtml":"<div class=\"souta-paper\"><div class=\"souta-paper-head\">夏休みの自由研究<br><strong>6年間の自由研究　そうたのパチスロ</strong><br>6年2組　星野 創太</div><h3>1年生のときの設計図</h3><img class=\"souta-blueprint\" src=\"images/embedded/e69bd28f7164383e.webp\" alt=\"小学1年生の創太が描いたパチスロの設計図\"><p>ぼくは今年の夏休みもパチスロを作りました。パチスロを作る自由研究は、今年で6年目です。でも6台作ったわけではありません。1年生のときに作った1台を、毎年なおしているので、ずっと同じパチスロです。</p><p>お父さんとお母さんは、二人ともパチスロを作る会社で働いています。家には古い部品や本がたくさんあります。勝手に使うとおこられるので、使っていい部品だけもらいます。作るのはぼくです。わからないことは聞くけど、答えを教えてもらうと自由研究じゃなくなるので、ヒントだけにしてもらっています。</p><p>1年生のとき、ぼくはまず設計図をかきました。リールが3つで、ボタンも3つです。下にはクマをかきました。お母さんは「犬かな」と言いました。ちがいます。クマです。ぼくはこの絵がとても気に入っています。</p><p>どうしてクマをかいたのかは、今となってはよくわかりません。でも、あのころ、どこかで見た黒い小さな動物がずっと頭に残っていました。あれはクマだったと思います。耳の形は、たぶんこんなだったと思います。</p><p>最初の台はダンボールでした。リールは紙で、手で回しました。ボタンも紙で、押しても何も起きません。お父さんに「それはボタンの絵だね」と言われました。ぼくもそう思いました。ちなみに、その日の晩ごはんはオムライスでした。ケチャップでリールをかこうとしたら、お母さんに食べ物で遊ばないでと言われました。遊んでいたわけではないけど、やめました。だから次の夏休みまでに、本当に回るようにしようと決めました。</p><p>2年生のときはモーターをつけました。三つのリールがそれぞれ回ったので、すごくうれしかったです。でも止めると絵柄がななめになりました。回転位置がわからないからです。そこで光センサーをつけて、基準位置を見つけるようにしました。最初は光が入ってまちがえたので、黒いテープで囲いました。</p><p>3年生のときは、ボタンを押したらリールが止まるようにしました。マイコンにプログラムを書きました。停止位置を決めるとき、いつも同じところで止まるとおもしろくありません。でも、何でも好きな絵柄に止められるのもおかしいです。そこで役を決めて、乱数で先に抽選するようにしました。乱数の種が同じだと結果がかたよったので、そこもなおしました。</p><p>4年生のときは、液晶をつけました。はじめは数字しか出ませんでした。絵を動かそうとしたら、処理が重くてリールの制御が遅れました。お父さんに「それはまずいね」と言われたので、表示と制御を別々にしました。音も鳴るようにしました。夜に試したらお母さんに怒られたので、音量調整もつけました。これはとても大事な機能だと思います。音量をゼロにするとお母さんに怒られません。でも、ぼくには何も聞こえません。むずかしい問題です。</p><p>ところで、ぼくはカレーが好きです。特にお母さんが作るカレーが好きです。じゃがいもが大きいからです。お父さんは中辛が好きだけど、ぼくは甘口のほうがおいしいと思います。去年はカレーを二回おかわりしました。</p><p>カレーの話は自由研究とは関係ありません。でも、4年生の夏休みにカレーを食べながら、液晶の処理とリールの制御を別々にすればいいと思いついたので、少しだけ関係があります。お母さんに話したら、食べてからにしなさいと言われました。</p><p>5年生のときは、筐体を作り直しました。強度を計算して金属の部品を組み合わせました。配線をまとめて、熱がこもらないようにしました。液晶の演出もたくさん作りました。大きな文字が光る演出は、どうしても入れたかったものです。文字は「PHANTOM」です。英語の授業で習った単語ではありません。ずっと前から知っている文字です。</p><p>今年、6年生の夏休みは、これまで作ったものを全部まとめました。回転制御、抽選、演出、音、ランプ、データの保存を一つの台にしました。テストをしていると、ときどき思っていない動きが出ます。原因を見つけて直すのは大変でした。ある日はバグを直したら別のバグが三つ出ました。三つ直したら最初のバグが帰ってきました。おかえりと言いたくなかったです。でも、うまく動いたときはとても楽しいです。</p><p>スペックも自分で考えました。今のパチスロがどんな性能なのか、本や資料をたくさん調べました。設定ごとの当たりやすさ、機械割、ATの純増、50枚で回せるゲーム数などを表にしました。ぼくの台の数値は目標値です。全部を実測したわけではありません。いろいろな台の数字をノートに書いてくらべるのは楽しかったです。数が多すぎて、算数のノートが一冊なくなりました。先生には計算が好きなんだねと言われました。たぶんそうです。でも、パチスロの計算がいちばん好きです。</p><p>いちばん時間がかかったのは、いちばん最初の設計図と見くらべることでした。ぼくは1年生のときの絵を机の上に置いて、毎年それを見ながら作ってきました。6年生になったら、あの絵のとおりのパチスロが完成しているはずでした。</p><p>でも、完成した台を見たら、ぜんぜんちがいました。リールのまわりも、ボタンの位置も、液晶の大きさも、1年生のぼくがかいたものとはちがいます。かっこよくなったところもあるけど、それは設計図どおりにできたということではありません。</p><p>だから、今年の自由研究は失敗です。</p><p>6年間も作ったのに、最初にかいたものをそのまま作ることができませんでした。ちょっとくやしいです。六年間の自由研究を一枚の紙にまとめようとしたら、字が小さすぎて自分でも読めませんでした。だから、こうして長く書いています。お父さんは「十分すごいよ」と言いました。お母さんも「よくがんばったね」と言いました。でも、ぼくが作りたかったのは、1年生のぼくがかいた、あのパチスロです。</p><p>ただ、一つだけ、ずっと変えていないところがあります。下のパネルのクマです。色はきれいになったけど、顔はあのときのままです。お母さんは今でも犬みたいだと言います。ぼくは今でもクマだと思います。</p><p>来年は中学生になるので、夏休みの自由研究はもうありません。だから、このパチスロを自由研究として作るのは今年でおしまいです。失敗したけど、6年間ずっと楽しかったです。</p><p>ぼくが1年生のときに見た、あのパチスロは、今はどこにあるんだろう。名前も場所も、ちゃんとは思い出せません。でも、光っていた文字と、下にいた小さなクマだけは、なぜか忘れません。</p><p>もし、また会えたら、ぼくのパチスロを見せてみたいです。</p><p>おわり。</p><div class=\"souta-teacher\">たいへんよくできました　◎<small>6年間、あきらめずに続けたことがすばらしいです。</small></div></div><h3>6年目の完成作品</h3><img class=\"ph-image\" src=\"__SOUTA_FINAL_IMAGE__\" alt=\"星野創太が6年間かけて完成させたパチスロ筐体\">"});
