 modalbg.classList.add('cinema-modal');
 const pane=$ph('mel404Cinema'),frame=pane.querySelector('.mel404-frame'),im=$ph('mel404CinemaImg'),close=pane.querySelector('.cinema-close');
 const timers=[];let stopped=false;
 const live=()=>!stopped&&pane.isConnected&&modalbg.classList.contains('open');
