 const finish=()=>{if(!live())return;pane.classList.add('mel404-end');close.focus({preventScroll:true})};
 close.addEventListener('click',()=>{cleanup();modalbg.classList.remove('open','cinema-modal');document.body.classList.remove('modal-open');document.body.style.overflow='';});
