function discover(m){
 if(!m || (!window.__kichiPhantomPreview&&(found.includes(m.id)||(m.id!=='phantom'&&!found.includes('phantom')))))return;
 if(m.id==='mel404'){open404Cinema(m);return;}
 // Keep the original mystery visible until the discovery animation finishes.
 const fields=[
  ['メーカー',m.maker],['導入年月日',m.date],['タイプ',m.type],
  ['純増',m.pure],['機械割',m.rate],[m.id==='phantom'?'初当たり':m.id==='meldisgust'?'ボーナス確率':'AT初当たり',m.hit]
 ];
 const gibberish=['縺ｿ繧ｨ譁�','螟ｱ謨励ｷ','繝ｼ繧ｫ','譛ｪ隧ｱ','蜈ｨ譁�','▒▓縺�'];
 const garble=(str,shift)=>Array.from(str).map((ch,i)=>/\s/.test(ch)?ch:gibberish[(i+shift)%gibberish.length][(i+shift)%3]||'▒').join('');
 const title='<h2 class="ph-decode" data-final="'+htmlEscape(m.name)+'">'+htmlEscape(m.id==='veil'?'縺▒譁�繧ｿ▒▓':garble(m.name,1))+'</h2>';
 const basics=fields.map(([label,value],i)=>'<p><b>'+label+'：</b><span class="ph-decode" data-final="'+htmlEscape(value)+'">'+htmlEscape(m.id==='veil'?'▒縺譁�▓▒':garble(value,i))+'</span></p>').join('');
 const phantomTagline=m.id==='phantom'?'<p class="ph-first-tagline" style="text-align:center;font-weight:700;letter-spacing:.08em;color:#dfb6e9;margin:10px 0 18px">これが、裏への入口。</p>':'';
 const markup='<div class="form phantom-detail ph-reveal" id="phantomReveal">'+title+phantomTagline+
  '<div class="phantom-info">'+basics+'</div>'+
  '<div class="ph-image-stage"><img class="ph-image" src="'+(m.id==='souta'?(m.storyHtml.match(/class="souta-blueprint" src="([^"]+)"/)?.[1]||m.image):m.image)+'" alt="復元中の架空パチスロ筐体" loading="eager"></div>'+
  '<p class="ph-reveal-status" aria-live="polite">RECONSTRUCTING DATA...</p>'+
  '<p class="phantom-note ph-reveal-note">'+(window.__kichiPhantomPreview?'【テスト再生】コレクションへの登録は行いません。':'PHANTOM COLLECTION に新たな機種が登録されました。')+'</p>'+
  '<p class="phantom-note">※ 架空の遊技機・架空のスペックです。</p>'+
  '<button type="button" class="btn ghost" data-close-modal="1">閉じる</button></div>';
 modal('縺ｿ繧ｨ譁�▒▒▒',markup);
 const pane=$ph('phantomReveal');
 if(!pane)return;
 pane.querySelector('[data-close-modal]').addEventListener('click',()=>{if(!finished)complete();},true);
 const nodes=Array.from(pane.querySelectorAll('[data-final]'));
 const stage=pane.querySelector('.ph-image-stage');
 const status=pane.querySelector('.ph-reveal-status');
 const begin=performance.now();
 const duration=3400;
 let finished=false;
 function complete(){
  if(finished)return;
  finished=true;
  nodes.forEach(n=>{n.textContent=n.dataset.final;n.classList.add('ph-decoded');});
  stage.classList.add('ph-clear');
  pane.classList.add('ph-finished');
  status.textContent=window.__kichiPhantomPreview?'DATA RESTORED / TEST PREVIEW':'DATA RESTORED / COLLECTION REGISTERED';
  const heading=$ph('modalTitle');if(heading)heading.textContent=m.name;
  if(!window.__kichiPhantomPreview && !found.includes(m.id)){
   registerFound(m);
  }
  if(!window.__kichiPhantomPreview){if(pending && pending.id===m.id){pending=null;try{localStorage.removeItem(MYSTERY_STORE)}catch(e){}}
  refreshMenu();renderPhantom();renderMystery();}
 }
 function tick(now){
  if(!pane.isConnected || !$ph('modalbg').classList.contains('open')){return;}
  const progress=Math.min(1,(now-begin)/duration);
  nodes.forEach((n,i)=>{
   const final=n.dataset.final;
   const count=Math.floor(final.length*Math.max(0,Math.min(1,(progress-.06*i)*1.65)));
   const remaining=final.slice(count);
   n.textContent=final.slice(0,count)+garble(remaining,Math.floor(now/110)+i);
   if(count>=final.length)n.classList.add('ph-decoded');
  });
  if(progress>.06)stage.classList.add('ph-clear');
  if(progress>=1){complete();return;}
  requestAnimationFrame(tick);
 }
 // Reduced-motion users see the result immediately.
 if(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches)complete();
 else requestAnimationFrame(tick);
}
