function randomPlace(grid,node){
 const rows=Array.from(grid.querySelectorAll('[data-slot]'));
 if(!rows.length){grid.append(node);return}
 const ix=Math.floor(Math.random()*(rows.length+1));
 if(ix===rows.length)rows[rows.length-1].after(node);else rows[ix].before(node);
}
