const PH76_READY='kichiguy_ph76_ready_v1',PH76_VIEW='kichiguy_ph76_views_v1',PH76_QUANT='kichiguy_ph76_quantum_views_v1';
function ph76Load(key,fallback){try{return JSON.parse(localStorage.getItem(key)||'null')||fallback}catch(e){return fallback}}
let ph76Ready=ph76Load(PH76_READY,{}),ph76Views=ph76Load(PH76_VIEW,{}),ph76Quantum=ph76Load(PH76_QUANT,{});
function ph76Save(){try{localStorage.setItem(PH76_READY,JSON.stringify(ph76Ready));localStorage.setItem(PH76_VIEW,JSON.stringify(ph76Views));localStorage.setItem(PH76_QUANT,JSON.stringify(ph76Quantum))}catch(e){}}
function ph76Master(){return found.includes('phantom')}
function ph76Appear(id){if(!ph76Master()||found.includes(id)||ph76Ready[id])return;ph76Ready[id]=true;ph76Save();renderMystery();if(id==='quantum'){const bg=document.getElementById('modalbg');if(bg?.classList.contains('open')){const ob=new MutationObserver(()=>{if(!bg.classList.contains('open')){ob.disconnect();ph76Flash()}});ob.observe(bg,{attributes:true,attributeFilter:['class']})}else ph76Flash()}}
function ph76Flash(){const e=document.createElement('div');e.className='ph76-flash';e.textContent='QUANTUM SYSTEM INITIALIZING...';document.body.append(e);setTimeout(()=>e.remove(),2100)}
function ph76Check(){if(!ph76Master())return;
 const missions=ph76Load('kichiguy_seg_missions_v1',{});
 if(missions.alltriples)ph76Appear('akaseg');
 if(missions.ceiling200)ph76Appear('hikiweak');
 if(missions.inmuall)ph76Appear('inmuking');
 if(found.includes('aoseg')&&found.includes('akaseg')&&ph76Views.aoseg&&ph76Views.akaseg)ph76Appear('zeroseg');
 const all=(typeof data!=='undefined'?data.slots:[]).map(s=>String(s.id));
 if(all.length&&all.every(id=>ph76Quantum[id]))ph76Appear('quantum');
}
