let primitiveQuaking=false;
function ph76PrimitiveQuake(){
 if(primitiveQuaking)return;
 primitiveQuaking=true;
 // Lock the page at its exact scroll position; never freeze the JS thread.
 const y=window.scrollY;
 const body=document.body;
 const old={position:body.style.position,top:body.style.top,left:body.style.left,right:body.style.right,width:body.style.width};
 body.style.position='fixed';body.style.top=`-${y}px`;body.style.left='0';body.style.right='0';body.style.width='100%';
 body.classList.add('ph76-earthquake');
 // After five seconds, restore scrolling and start the original discovery.
 setTimeout(()=>{
  body.classList.remove('ph76-earthquake');
  Object.assign(body.style,old);
  window.scrollTo(0,y);
  primitiveQuaking=false;
  ph76Appear('primitive');
 },5000);
}
let ph76Touch=null,ph76PullCount=0;
document.addEventListener('touchstart',e=>{if(primitiveQuaking||!ph76Master()||found.includes('primitive')||ph76Ready.primitive||!document.getElementById('collection')?.classList.contains('active'))return;
 const atBottom=window.innerHeight+window.scrollY>=document.documentElement.scrollHeight-18;
 if(atBottom&&e.touches.length===1)ph76Touch={y:e.touches[0].clientY,time:Date.now(),counted:false};else ph76Touch=null;
},{passive:true});
document.addEventListener('touchend',e=>{if(!ph76Touch)return;const start=ph76Touch;ph76Touch=null;
 const end=e.changedTouches[0]?.clientY??start.y;
 if(end<start.y-45&&Date.now()-start.time<1800){ph76PullCount++;if(ph76PullCount>=5){ph76PullCount=0;ph76PrimitiveQuake()}}
},{passive:true});
// Mouse-wheel fallback for desktop testing, five separate downward gestures.
let ph76WheelLast=0;
document.addEventListener('wheel',e=>{if(primitiveQuaking||!ph76Master()||found.includes('primitive')||ph76Ready.primitive||!document.getElementById('collection')?.classList.contains('active'))return;
 if(window.innerHeight+window.scrollY<document.documentElement.scrollHeight-18||e.deltaY<45)return;
 const now=Date.now();if(now-ph76WheelLast<400)return;ph76WheelLast=now;
 ph76PullCount++;if(ph76PullCount>=5){ph76PullCount=0;ph76PrimitiveQuake()}
},{passive:true});
